// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ReportingInstallation) predicate.ReportingInstallation {
	return predicate.ReportingInstallation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ReportingInstallation) predicate.ReportingInstallation {
	return predicate.ReportingInstallation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ReportingInstallation) predicate.ReportingInstallation {
	return predicate.ReportingInstallation(sql.NotPredicates(p))
}
